import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

const canvas=document.querySelector('#game'), statusEl=document.querySelector('#status');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x8fc5e8);scene.fog=new THREE.Fog(0x8fc5e8,18,48);
const camera=new THREE.PerspectiveCamera(75,innerWidth/innerHeight,.1,100);camera.position.set(0,5,8);
const renderer=new THREE.WebGLRenderer({canvas,antialias:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.25));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=false;
scene.add(new THREE.HemisphereLight(0xd9efff,0x65734b,2));const sun=new THREE.DirectionalLight(0xffffff,1.25);sun.position.set(-8,15,7);scene.add(sun);
const materials={grass:new THREE.MeshLambertMaterial({color:0x65a843}),dirt:new THREE.MeshLambertMaterial({color:0x805333}),stone:new THREE.MeshLambertMaterial({color:0x858b8d}),wood:new THREE.MeshLambertMaterial({color:0x956334}),leaves:new THREE.MeshLambertMaterial({color:0x347b35}),sand:new THREE.MeshLambertMaterial({color:0xd7c17c})};
const blockGeo=new THREE.BoxGeometry(1,1,1), blocks=new Map(), meshes=new Map();const key=(x,y,z)=>`${x},${y},${z}`;
function put(x,y,z,type){const k=key(x,y,z);if(blocks.has(k))return;blocks.set(k,type);const m=new THREE.Mesh(blockGeo,materials[type]||materials.dirt);m.position.set(x,y,z);m.userData={x,y,z};scene.add(m);meshes.set(k,m)}
function remove(x,y,z){const k=key(x,y,z),m=meshes.get(k);if(!m)return;scene.remove(m);m.material.dispose?.();meshes.delete(k);blocks.delete(k)}
function height(x,z){return Math.floor(2+Math.sin(x*.22)*1.2+Math.cos(z*.19)*1.1)}
function tree(x,z){const y=height(x,z);for(let i=1;i<=3;i++)put(x,y+i,z,'wood');for(let dx=-2;dx<=2;dx++)for(let dz=-2;dz<=2;dz++)for(let dy=2;dy<=4;dy++)if(Math.abs(dx)+Math.abs(dz)+(dy===4?1:0)<5)put(x+dx,y+dy,z+dz,'leaves')}
function generate(){for(let x=-12;x<=12;x++)for(let z=-12;z<=12;z++){const h=height(x,z);for(let y=-2;y<=h;y++)put(x,y,z,y===h?'grass':y>h-3?'dirt':'stone');if((Math.abs(x*13+z*7)%79)===0&&Math.abs(x)+Math.abs(z)>4)tree(x,z)}}
generate();
const player={pos:new THREE.Vector3(0,6,7),vel:new THREE.Vector3(),yaw:0,pitch:0,onGround:false};const keys={},inventory={grass:32,dirt:32,stone:16,wood:8,sand:8,leaves:8},types=Object.keys(materials);let selected='grass';
const ray=new THREE.Raycaster();function target(){ray.setFromCamera(new THREE.Vector2(0,0),camera);return ray.intersectObjects([...meshes.values()],false)[0]||null}
function updateHUD(){document.querySelector('#hotbar').innerHTML=types.map((t,i)=>`<div class="slot ${t===selected?'active':''}" data-type="${t}"><div class="swatch" style="background:#${materials[t].color.getHexString()}"></div>${i+1}</div>`).join('');document.querySelectorAll('.slot').forEach(el=>el.onclick=()=>{selected=el.dataset.type;updateHUD()})}
updateHUD();
function mine(){const hit=target();if(!hit)return;const {x,y,z}=hit.object.userData;const type=blocks.get(key(x,y,z));remove(x,y,z);inventory[type]=(inventory[type]||0)+1;statusEl.textContent=`Quebrou ${type} · ${inventory[type]}`}
function place(){const hit=target();if(!hit||!inventory[selected])return;const n=hit.face.normal.clone().transformDirection(hit.object.matrixWorld);const p=hit.object.position.clone().add(n);const x=Math.round(p.x),y=Math.round(p.y),z=Math.round(p.z);if(Math.abs(x-player.pos.x)<.8&&Math.abs(z-player.pos.z)<.8&&y>=player.pos.y-1&&y<=player.pos.y+1)return;put(x,y,z,selected);inventory[selected]--;statusEl.textContent=`Colocou ${selected} · restam ${inventory[selected]}`}
const clock=new THREE.Clock();function solidAt(x,y,z){return blocks.has(key(Math.round(x),Math.round(y),Math.round(z)))}
function physics(dt){const speed=keys.Shift?7:4.5,forward=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw)),right=new THREE.Vector3(Math.cos(player.yaw),0,-Math.sin(player.yaw));const move=new THREE.Vector3();if(keys.KeyW||keys.ArrowUp)move.add(forward);if(keys.KeyS||keys.ArrowDown)move.sub(forward);if(keys.KeyD||keys.ArrowRight)move.add(right);if(keys.KeyA||keys.ArrowLeft)move.sub(right);if(move.lengthSq())move.normalize().multiplyScalar(speed);player.vel.x=move.x;player.vel.z=move.z;player.vel.y-=19*dt;
let nx=player.pos.x+player.vel.x*dt,nz=player.pos.z+player.vel.z*dt,ny=player.pos.y+player.vel.y*dt;
if(!solidAt(nx,player.pos.y-.9,player.pos.z)&&!solidAt(nx,player.pos.y+.1,player.pos.z))player.pos.x=nx;else player.vel.x=0;
if(!solidAt(player.pos.x,player.pos.y-.9,nz)&&!solidAt(player.pos.x,player.pos.y+.1,nz))player.pos.z=nz;else player.vel.z=0;
player.onGround=false;if(player.vel.y<=0&&(solidAt(player.pos.x,ny-.9,player.pos.z)||solidAt(player.pos.x-.3,ny-.9,player.pos.z)||solidAt(player.pos.x+.3,ny-.9,player.pos.z))){player.pos.y=Math.floor(ny-.9)+1.9;player.vel.y=0;player.onGround=true}else if(player.vel.y>0&&solidAt(player.pos.x,ny+.1,player.pos.z)){player.vel.y=0}else player.pos.y=ny;
if(player.pos.y< -10){player.pos.set(0,8,7);player.vel.set(0,0,0)}
camera.position.copy(player.pos);camera.rotation.order='YXZ';camera.rotation.y=player.yaw;camera.rotation.x=player.pitch}
function loop(){requestAnimationFrame(loop);const dt=Math.min(clock.getDelta(),.04);physics(dt);renderer.render(scene,camera)}loop();
addEventListener('keydown',e=>{keys[e.code]=true;if(/^Digit[1-6]$/.test(e.code)){selected=types[Number(e.code.slice(-1))-1];updateHUD()}if(e.code==='Space'&&player.onGround)player.vel.y=7.5;if(e.code==='KeyF')mine();if(e.code==='KeyG')place()});addEventListener('keyup',e=>keys[e.code]=false);
canvas.addEventListener('click',()=>{if(document.pointerLockElement!==canvas&&matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas){player.yaw-=e.movementX*.002;player.pitch=Math.max(-1.45,Math.min(1.45,player.pitch-e.movementY*.002))}});
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('mousedown',e=>{if(e.button===0)mine();if(e.button===2)place()});
let lookTouch=null;document.querySelector('#look').addEventListener('pointerdown',e=>{lookTouch={x:e.clientX,y:e.clientY};e.currentTarget.setPointerCapture(e.pointerId)});document.querySelector('#look').addEventListener('pointermove',e=>{if(!lookTouch)return;player.yaw-=(e.clientX-lookTouch.x)*.006;player.pitch=Math.max(-1.4,Math.min(1.4,player.pitch-(e.clientY-lookTouch.y)*.006));lookTouch={x:e.clientX,y:e.clientY}});document.querySelector('#look').addEventListener('pointerup',()=>lookTouch=null);
document.querySelectorAll('[data-move]').forEach(b=>{const code={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'}[b.dataset.move];b.addEventListener('pointerdown',e=>{keys[code]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[code]=false))});
document.querySelector('#jump').onclick=()=>{if(player.onGround)player.vel.y=7.5};document.querySelector('#break').onclick=mine;document.querySelector('#place').onclick=place;
function save(){const data={blocks:[...blocks.entries()],player:{x:player.pos.x,y:player.pos.y,z:player.pos.z,yaw:player.yaw},inventory,selected};const req=indexedDB.open('weblab-worlds',1);req.onupgradeneeded=()=>req.result.createObjectStore('worlds');req.onsuccess=()=>{const db=req.result,tx=db.transaction('worlds','readwrite');tx.objectStore('worlds').put(data,'slot-1');tx.oncomplete=()=>statusEl.textContent='Mundo salvo localmente'};req.onerror=()=>statusEl.textContent='Falha ao salvar'}
function load(){const req=indexedDB.open('weblab-worlds',1);req.onupgradeneeded=()=>req.result.createObjectStore('worlds');req.onsuccess=()=>{const r=req.result.transaction('worlds').objectStore('worlds').get('slot-1');r.onsuccess=()=>{if(!r.result)return;for(const m of meshes.values())scene.remove(m);blocks.clear();meshes.clear();r.result.blocks.forEach(([k,t])=>{const [x,y,z]=k.split(',').map(Number);put(x,y,z,t)});Object.assign(inventory,r.result.inventory);player.pos.set(r.result.player.x,r.result.player.y,r.result.player.z);player.yaw=r.result.player.yaw;selected=r.result.selected;updateHUD();statusEl.textContent='Mundo carregado'}}}
document.querySelector('#start').onclick=()=>{document.querySelector('#menu').style.display='none';load();if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.()};
document.querySelector('#save').onclick=save;document.querySelector('#reset').onclick=()=>{if(confirm('Criar mundo novo? O salvamento local será substituído.')){indexedDB.deleteDatabase('weblab-worlds');location.reload()}};
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.25))});
statusEl.textContent='Mundo pronto · '+blocks.size+' blocos';
